INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('sea level rise', '', '', '[{"en":"Sea level rise threatens coastal cities around the world.","zh-TW":"海平面上升威脅著世界各地的沿海城市。"},{"en":"Climate action is urgently needed to slow sea level rise.","zh-TW":"迫切需要氣候行動來減緩海平面上升。"}]', 'phrasal verb'),
('binding agreement', '', '', '[{"en":"By signing, you enter into a legally binding agreement.","zh-TW":"簽署後，您進入具有法律約束力的協議。"},{"en":"The binding agreement outlines both parties'' responsibilities.","zh-TW":"具有法律約束力的協議概述了雙方的責任。"}]', 'phrasal verb'),
('cease and desist', '', '', '[{"en":"The company sent a cease and desist letter to the imitator.","zh-TW":"公司向仿冒者發送了停止侵害通知函。"},{"en":"Ignoring a cease and desist can result in a court injunction.","zh-TW":"無視停止侵害令可能導致法院禁令。"}]', 'phrasal verb'),
('civil law', '', '', '[{"en":"The dispute was handled under civil law.","zh-TW":"該爭議依民法處理。"},{"en":"Civil law covers contracts, property, and family matters.","zh-TW":"民法涵蓋合約、財產和家庭事務。"}]', 'phrasal verb'),
('implied contract', '', '', '[{"en":"An implied contract can exist even without a written document.","zh-TW":"即使沒有書面文件，默示合約也可以存在。"},{"en":"Accepting the service created an implied contract with the provider.","zh-TW":"接受服務與提供者之間產生了默示合約。"}]', 'phrasal verb'),
('letter of intent', '', '', '[{"en":"Both parties signed a letter of intent before finalizing the deal.","zh-TW":"雙方在完成交易前簽署了意向書。"},{"en":"A letter of intent is not legally binding but shows serious interest.","zh-TW":"意向書不具法律約束力，但表示認真的意向。"}]', 'phrasal verb'),
('memorandum of understanding', '', '', '[{"en":"They signed a memorandum of understanding to begin collaboration.","zh-TW":"他們簽署了諒解備忘錄開始合作。"},{"en":"A memorandum of understanding outlines the key terms before a formal contract.","zh-TW":"諒解備忘錄在正式合約之前概述了關鍵條款。"}]', 'phrasal verb'),
('power of attorney', '', '', '[{"en":"She granted her son power of attorney to manage her finances.","zh-TW":"她授予她的兒子管理財務的授權書。"},{"en":"A power of attorney must be notarized to be legally valid.","zh-TW":"授權書必須公證才能具有法律效力。"}]', 'phrasal verb'),
('statute of limitations', '', '', '[{"en":"The lawsuit was filed before the statute of limitations expired.","zh-TW":"訴訟在訴訟時效到期前提起。"},{"en":"The statute of limitations for contract disputes varies by jurisdiction.","zh-TW":"合約爭議的訴訟時效因司法管轄區而異。"}]', 'phrasal verb'),
('accident report', '', '', '[{"en":"An accident report must be submitted within 24 hours.","zh-TW":"事故報告必須在24小時內提交。"},{"en":"The accident report described how the injury occurred.","zh-TW":"事故報告描述了受傷是如何發生的。"}]', 'phrasal verb'),
('building code', '', '', '[{"en":"All renovations must comply with local building codes.","zh-TW":"所有翻新工程必須符合當地建築法規。"},{"en":"The inspection found several building code violations.","zh-TW":"檢查發現了幾項建築法規違規行為。"}]', 'phrasal verb'),
('compliance officer', '', '', '[{"en":"The compliance officer reviewed all company policies for legal adherence.","zh-TW":"合規主任審查了所有公司政策的法律合規性。"},{"en":"Concerns about misconduct should be reported to the compliance officer.","zh-TW":"關於不當行為的顧慮應向合規主任報告。"}]', 'phrasal verb'),
('emergency exit', '', '', '[{"en":"Familiarize yourself with the emergency exits upon arrival.","zh-TW":"抵達時請熟悉緊急出口的位置。"},{"en":"Emergency exit signs must be illuminated at all times.","zh-TW":"緊急出口標誌必須始終保持照明。"}]', 'phrasal verb'),
('fire drill', '', '', '[{"en":"The office conducts a fire drill every six months.","zh-TW":"辦公室每六個月進行一次消防演習。"},{"en":"All employees must participate in the scheduled fire drill.","zh-TW":"所有員工必須參加定期的消防演習。"}]', 'phrasal verb'),
('fire extinguisher', '', '', '[{"en":"Know how to operate a fire extinguisher in an emergency.","zh-TW":"了解如何在緊急情況下使用滅火器。"},{"en":"Fire extinguishers must be inspected and recharged regularly.","zh-TW":"滅火器必須定期檢查和充裝。"}]', 'phrasal verb'),
('health and safety', '', '', '[{"en":"All employees must follow the company''s health and safety policy.","zh-TW":"所有員工必須遵守公司的健康與安全政策。"},{"en":"Health and safety audits are conducted twice a year.","zh-TW":"健康與安全審核每年進行兩次。"}]', 'phrasal verb'),
('incident report', '', '', '[{"en":"All incidents, however minor, must be documented in an incident report.","zh-TW":"所有事件，無論多小，都必須記錄在事件報告中。"},{"en":"The incident report was submitted to the safety committee.","zh-TW":"事件報告已提交給安全委員會。"}]', 'phrasal verb'),
('liability insurance', '', '', '[{"en":"Professional liability insurance protects consultants from claims.","zh-TW":"專業責任保險保護顧問免受索賠。"},{"en":"The company carries comprehensive liability insurance.","zh-TW":"公司持有全面的責任保險。"}]', 'phrasal verb'),
('occupational health', '', '', '[{"en":"The company offers an occupational health assessment for all employees.","zh-TW":"公司為所有員工提供職業健康評估。"},{"en":"Occupational health programs reduce absenteeism and improve productivity.","zh-TW":"職業健康計劃減少了缺勤並提高了生產力。"}]', 'phrasal verb'),
('personal protective equipment', '', '', '[{"en":"Personal protective equipment is mandatory on the construction site.","zh-TW":"建設工地上必須佩戴個人防護裝備。"},{"en":"Inspect personal protective equipment before each use.","zh-TW":"每次使用前請檢查個人防護裝備。"}]', 'phrasal verb'),
('risk assessment', '', '', '[{"en":"A risk assessment must be completed before the project begins.","zh-TW":"項目開始前必須完成風險評估。"},{"en":"Regular risk assessments help prevent workplace accidents.","zh-TW":"定期風險評估有助於預防工作場所事故。"}]', 'phrasal verb'),
('safety officer', '', '', '[{"en":"The safety officer conducted the monthly safety inspection.","zh-TW":"安全主任進行了每月安全檢查。"},{"en":"Contact the safety officer if you observe a potential hazard.","zh-TW":"如果您發現潛在危害，請聯繫安全主任。"}]', 'phrasal verb'),
('security badge', '', '', '[{"en":"All employees must wear their security badge at all times.","zh-TW":"所有員工必須隨時佩戴安全通行證。"},{"en":"Visitors are issued a temporary security badge at reception.","zh-TW":"訪客在接待處領取臨時安全通行證。"}]', 'phrasal verb'),
('workplace injury', '', '', '[{"en":"All workplace injuries must be reported immediately.","zh-TW":"所有工作場所傷害必須立即報告。"},{"en":"The company implemented new procedures to reduce workplace injuries.","zh-TW":"公司實施了新程序以減少工作場所傷害。"}]', 'phrasal verb'),
('benchmark test', '', '', '[{"en":"The IT team ran a benchmark test on the new servers.","zh-TW":"IT團隊在新伺服器上進行了基準測試。"},{"en":"Benchmark tests help compare performance across systems.","zh-TW":"基準測試有助於比較各系統的性能。"}]', 'phrasal verb'),
('board meeting', '', '', '[{"en":"The board meeting approved the expansion strategy.","zh-TW":"董事會會議批准了擴張策略。"},{"en":"Minutes of the board meeting are distributed within 48 hours.","zh-TW":"董事會會議記錄在48小時內分發。"}]', 'phrasal verb'),
('collective agreement', '', '', '[{"en":"The union reached a collective agreement with management.","zh-TW":"工會與管理層達成了集體協議。"},{"en":"Wage increases were specified in the collective agreement.","zh-TW":"集體協議中規定了薪資增加幅度。"}]', 'phrasal verb'),
('competitive pricing', '', '', '[{"en":"The company uses competitive pricing to attract new customers.","zh-TW":"公司採用競爭性定價來吸引新顧客。"},{"en":"Competitive pricing requires regular market analysis.","zh-TW":"競爭性定價需要定期的市場分析。"}]', 'phrasal verb'),
('contingency plan', '', '', '[{"en":"A contingency plan was prepared in case of supply chain disruption.","zh-TW":"準備了應急計劃以防止供應鏈中斷。"},{"en":"Activating the contingency plan helped minimize disruption.","zh-TW":"啟動應急計劃幫助將中斷降到最低。"}]', 'phrasal verb'),
('credit limit', '', '', '[{"en":"Her credit limit was increased after a year of good standing.","zh-TW":"她在一年的良好記錄後信用額度得到提升。"},{"en":"The transaction was declined because the credit limit was exceeded.","zh-TW":"交易因超出信用額度而被拒絕。"}]', 'phrasal verb'),
('data breach', '', '', '[{"en":"The company suffered a major data breach affecting 500,000 customers.","zh-TW":"公司遭遇了影響500,000名顧客的重大數據洩露。"},{"en":"A data breach response plan must be in place before an incident occurs.","zh-TW":"數據洩露應對計劃必須在事件發生前就位。"}]', 'phrasal verb'),
('headquarters relocation', '', '', '[{"en":"The company announced a headquarters relocation to reduce costs.","zh-TW":"公司宣布了總部遷移以降低成本。"},{"en":"The headquarters relocation took six months to complete.","zh-TW":"總部遷移花了六個月完成。"}]', 'phrasal verb'),
('income tax return', '', '', '[{"en":"All employees must file an income tax return by April 30th.","zh-TW":"所有員工必須在4月30日前申報所得稅。"},{"en":"An accountant helped her complete the income tax return accurately.","zh-TW":"會計師幫助她準確完成了所得稅申報單。"}]', 'phrasal verb'),
('knowledge base', '', '', '[{"en":"The IT department maintains a knowledge base for common issues.","zh-TW":"IT部門為常見問題維護了知識庫。"},{"en":"Employees can find answers in the company knowledge base.","zh-TW":"員工可以在公司知識庫中找到答案。"}]', 'phrasal verb'),
('lump sum', '', '', '[{"en":"She chose to receive her pension as a lump sum.","zh-TW":"她選擇以一次性付款的方式領取養老金。"},{"en":"A lump sum payment was made to settle the debt in full.","zh-TW":"一次性付款用於全額結清債務。"}]', 'phrasal verb'),
('money laundering', '', '', '[{"en":"Banks must implement anti-money laundering controls.","zh-TW":"銀行必須實施反洗錢管控措施。"},{"en":"The compliance team monitors transactions to detect money laundering.","zh-TW":"合規團隊監控交易以發現洗錢行為。"}]', 'phrasal verb'),
('on-the-job training', '', '', '[{"en":"New employees receive on-the-job training for the first two weeks.","zh-TW":"新員工在前兩週接受在職培訓。"},{"en":"On-the-job training is often more effective than classroom instruction.","zh-TW":"在職培訓通常比課堂教學更有效。"}]', 'phrasal verb'),
('open-ended question', '', '', '[{"en":"Open-ended questions encourage more thoughtful responses.","zh-TW":"開放性問題鼓勵更有深度的回覆。"},{"en":"Interviewers use open-ended questions to assess candidates fully.","zh-TW":"面試官使用開放性問題全面評估候選人。"}]', 'phrasal verb'),
('peer review', '', '', '[{"en":"The research paper underwent rigorous peer review before publication.","zh-TW":"研究論文在發表前經過了嚴格的同儕審查。"},{"en":"Peer reviews help maintain high standards in academic and professional settings.","zh-TW":"同儕審查有助於在學術和專業環境中保持高標準。"}]', 'phrasal verb'),
('pilot project', '', '', '[{"en":"The company ran a pilot project before rolling out nationwide.","zh-TW":"公司在全國推廣之前進行了試行計劃。"},{"en":"Lessons learned from the pilot project improved the final design.","zh-TW":"從試行計劃中學到的經驗改善了最終設計。"}]', 'phrasal verb'),
('project scope', '', '', '[{"en":"The project scope was clearly defined at the kickoff meeting.","zh-TW":"項目範圍在啟動會議上明確界定了。"},{"en":"Scope creep can cause delays and budget overruns.","zh-TW":"範圍蔓延可能導致延誤和預算超支。"}]', 'phrasal verb'),
('purchase agreement', '', '', '[{"en":"A purchase agreement was signed before the handover.","zh-TW":"在移交前簽署了購買協議。"},{"en":"Review the purchase agreement carefully before signing.","zh-TW":"簽署前請仔細審查購買協議。"}]', 'phrasal verb'),
('reference number', '', '', '[{"en":"Please quote your reference number when contacting customer service.","zh-TW":"聯繫客服時請提供您的參考號碼。"},{"en":"The reference number is located on the top of your invoice.","zh-TW":"參考號碼位於您的發票頂部。"}]', 'phrasal verb'),
('remote access', '', '', '[{"en":"Employees require remote access to company systems when traveling.","zh-TW":"員工在出差時需要遠端訪問公司系統。"},{"en":"Remote access must be secured with multi-factor authentication.","zh-TW":"遠端訪問必須通過多因素驗證加以保護。"}]', 'phrasal verb'),
('revenue forecast', '', '', '[{"en":"The revenue forecast for next year showed 20% growth.","zh-TW":"明年的收益預測顯示增長20%。"},{"en":"Management revised the revenue forecast after the market downturn.","zh-TW":"管理層在市場下滑後修訂了收益預測。"}]', 'phrasal verb'),
('sales target', '', '', '[{"en":"The team met its quarterly sales target ahead of schedule.","zh-TW":"團隊提前完成了季度銷售目標。"},{"en":"Incentives are offered for exceeding the annual sales target.","zh-TW":"超過年度銷售目標可獲得獎勵。"}]', 'phrasal verb'),
('settlement date', '', '', '[{"en":"The settlement date for the property purchase is June 30th.","zh-TW":"房產購買的結算日為6月30日。"},{"en":"Funds must be available on the settlement date.","zh-TW":"資金必須在結算日準備好。"}]', 'phrasal verb'),
('short-term goal', '', '', '[{"en":"Setting short-term goals helps maintain focus and momentum.","zh-TW":"設定短期目標有助於保持專注和動力。"},{"en":"Her short-term goal is to complete the certification this year.","zh-TW":"她的短期目標是今年完成認證。"}]', 'phrasal verb'),
('site visit', '', '', '[{"en":"The client requested a site visit to check construction progress.","zh-TW":"客戶要求進行現場參觀以查看施工進展。"},{"en":"A site visit revealed several issues that needed immediate attention.","zh-TW":"現場視察發現了幾個需要立即處理的問題。"}]', 'phrasal verb'),
('stakeholder report', '', '', '[{"en":"The annual stakeholder report summarizes company performance.","zh-TW":"年度利害關係人報告總結了公司的表現。"},{"en":"All stakeholder reports must be reviewed by senior management.","zh-TW":"所有利害關係人報告必須由高層管理人員審查。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('steering committee', '', '', '[{"en":"The project''s steering committee meets monthly to review progress.","zh-TW":"項目指導委員會每月開會審查進展。"},{"en":"The steering committee approved the revised project scope.","zh-TW":"指導委員會批准了修訂後的項目範圍。"}]', 'phrasal verb'),
('task delegation', '', '', '[{"en":"Effective task delegation allows managers to focus on strategy.","zh-TW":"有效的任務委派允許管理者專注於策略。"},{"en":"She improved team productivity through smart task delegation.","zh-TW":"她透過聰明的任務委派提高了團隊生產力。"}]', 'phrasal verb'),
('terms of payment', '', '', '[{"en":"Standard terms of payment are net 30 days.","zh-TW":"標準的付款條件是30天內付清。"},{"en":"The supplier requested different terms of payment for large orders.","zh-TW":"供應商要求大訂單採用不同的付款條件。"}]', 'phrasal verb'),
('trade discount', '', '', '[{"en":"Retailers receive a 20% trade discount from the manufacturer.","zh-TW":"零售商從製造商獲得20%的貿易折扣。"},{"en":"A larger order size qualifies for a higher trade discount.","zh-TW":"較大的訂量可享有更高的貿易折扣。"}]', 'phrasal verb'),
('transaction fee', '', '', '[{"en":"International wire transfers carry a transaction fee.","zh-TW":"國際電匯需要支付交易費用。"},{"en":"Some credit cards offer no transaction fees on foreign purchases.","zh-TW":"某些信用卡對境外購物不收取交易費用。"}]', 'phrasal verb'),
('trend analysis', '', '', '[{"en":"Trend analysis revealed a steady decline in customer complaints.","zh-TW":"趨勢分析顯示顧客投訴穩步下降。"},{"en":"Investors rely on trend analysis to make informed decisions.","zh-TW":"投資者依靠趨勢分析做出明智決策。"}]', 'phrasal verb'),
('unit cost', '', '', '[{"en":"Increasing production volume can reduce the unit cost.","zh-TW":"增加生產量可以降低單位成本。"},{"en":"The unit cost of the product decreased with automation.","zh-TW":"自動化降低了產品的單位成本。"}]', 'phrasal verb'),
('accreditation body', '', '', '[{"en":"The school is recognized by a leading international accreditation body.","zh-TW":"這所學校獲得了頂尖的國際認證機構的認可。"},{"en":"Accreditation bodies set standards for educational quality.","zh-TW":"認證機構為教育品質設定標準。"}]', 'phrasal verb'),
('aggregate demand', '', '', '[{"en":"Lower interest rates can boost aggregate demand.","zh-TW":"降低利率可以提振總需求。"},{"en":"The recession caused aggregate demand to fall significantly.","zh-TW":"經濟衰退導致總需求大幅下降。"}]', 'phrasal verb'),
('asset management', '', '', '[{"en":"She works at an asset management company specializing in equity.","zh-TW":"她在一家專門從事股票的資產管理公司工作。"},{"en":"Asset management ensures that resources are used efficiently.","zh-TW":"資產管理確保資源得到有效使用。"}]', 'phrasal verb'),
('billing cycle', '', '', '[{"en":"The billing cycle is 30 days from the date of service.","zh-TW":"計費週期為服務日期起30天。"},{"en":"Your statement arrives at the end of each billing cycle.","zh-TW":"您的帳單在每個計費週期結束時到達。"}]', 'phrasal verb'),
('brainstorming session', '', '', '[{"en":"The team held a brainstorming session to develop new product ideas.","zh-TW":"團隊舉行了腦力激盪會議以開發新產品創意。"},{"en":"A good brainstorming session builds team creativity.","zh-TW":"良好的腦力激盪會議能夠增強團隊創造力。"}]', 'phrasal verb'),
('bulk order', '', '', '[{"en":"We placed a bulk order to take advantage of the discount.","zh-TW":"我們下了大宗訂單以享受折扣優惠。"},{"en":"Bulk orders are typically processed with a longer lead time.","zh-TW":"大宗訂單通常有較長的前置時間。"}]', 'phrasal verb'),
('career development', '', '', '[{"en":"The company invests in employee career development.","zh-TW":"公司投資於員工的職涯發展。"},{"en":"A good manager supports the career development of their team.","zh-TW":"優秀的管理者支持其團隊成員的職涯發展。"}]', 'phrasal verb'),
('cash register', '', '', '[{"en":"The cashier processed the transaction using the cash register.","zh-TW":"收銀員使用收銀機處理了交易。"},{"en":"Modern cash registers can also process card payments.","zh-TW":"現代收銀機也可以處理刷卡付款。"}]', 'phrasal verb'),
('certified public accountant', '', '', '[{"en":"She hired a certified public accountant to prepare her tax return.","zh-TW":"她聘請了注冊會計師準備她的稅務申報。"},{"en":"Our accounts are audited by a certified public accountant annually.","zh-TW":"我們的帳目每年由注冊會計師審計。"}]', 'phrasal verb'),
('column chart', '', '', '[{"en":"The column chart showed sales growth over five years.","zh-TW":"柱狀圖顯示了五年來的銷售增長情況。"},{"en":"Use a column chart to compare data across categories.","zh-TW":"使用柱狀圖比較不同類別的數據。"}]', 'phrasal verb'),
('commercial invoice', '', '', '[{"en":"A commercial invoice is required for all international shipments.","zh-TW":"所有國際貨運都需要商業發票。"},{"en":"The commercial invoice must describe the goods and their value.","zh-TW":"商業發票必須描述貨物及其價值。"}]', 'phrasal verb'),
('contract renewal', '', '', '[{"en":"The contract renewal was negotiated two months before expiry.","zh-TW":"合約續簽在到期前兩個月進行了談判。"},{"en":"Clients receive a reminder 30 days before contract renewal.","zh-TW":"顧客在合約續簽前30天收到提醒。"}]', 'phrasal verb'),
('core values', '', '', '[{"en":"The company''s core values include integrity and innovation.","zh-TW":"公司的核心價值觀包括誠信和創新。"},{"en":"Employees are expected to reflect the organization''s core values.","zh-TW":"員工應體現組織的核心價值觀。"}]', 'phrasal verb'),
('corporate governance', '', '', '[{"en":"Good corporate governance builds investor trust.","zh-TW":"良好的企業管治建立了投資者信任。"},{"en":"The board is responsible for upholding corporate governance standards.","zh-TW":"董事會負責維護公司治理標準。"}]', 'phrasal verb'),
('credit score', '', '', '[{"en":"A high credit score makes it easier to get a loan.","zh-TW":"高信用評分使獲得貸款更容易。"},{"en":"Missing payments can significantly lower your credit score.","zh-TW":"錯過付款可能大幅降低您的信用評分。"}]', 'phrasal verb'),
('data privacy', '', '', '[{"en":"The company is committed to protecting customer data privacy.","zh-TW":"公司致力於保護顧客的數據隱私。"},{"en":"Data privacy regulations require explicit consent before collection.","zh-TW":"數據隱私法規要求在收集前獲得明確同意。"}]', 'phrasal verb'),
('deadline management', '', '', '[{"en":"Effective deadline management is essential for project success.","zh-TW":"有效的截止日期管理對項目成功至關重要。"},{"en":"She is praised for her excellent deadline management skills.","zh-TW":"她因出色的截止日期管理技能而受到稱讚。"}]', 'phrasal verb'),
('declining industry', '', '', '[{"en":"Print media is often cited as a declining industry.","zh-TW":"印刷媒體經常被視為衰退行業的例子。"},{"en":"Companies in declining industries must innovate to survive.","zh-TW":"衰退行業中的公司必須創新才能生存。"}]', 'phrasal verb'),
('dispute resolution', '', '', '[{"en":"The contract includes a clause for alternative dispute resolution.","zh-TW":"合約包含替代性爭議解決條款。"},{"en":"Mediation is a common method of dispute resolution in business.","zh-TW":"調解是商業中常見的爭議解決方法。"}]', 'phrasal verb'),
('dividend policy', '', '', '[{"en":"The board revised the dividend policy to increase shareholder returns.","zh-TW":"董事會修訂了股利政策以增加股東回報。"},{"en":"A consistent dividend policy attracts income-focused investors.","zh-TW":"一致的股利政策吸引注重收益的投資者。"}]', 'phrasal verb'),
('efficiency ratio', '', '', '[{"en":"A lower efficiency ratio indicates better cost management.","zh-TW":"較低的效率比率表示更好的成本管理。"},{"en":"The bank''s efficiency ratio improved after restructuring.","zh-TW":"重組後銀行的效率比率有所改善。"}]', 'phrasal verb'),
('endorsement letter', '', '', '[{"en":"The professor provided an endorsement letter for the scholarship.","zh-TW":"教授為獎學金申請提供了推薦函。"},{"en":"An endorsement letter from a client strengthens the proposal.","zh-TW":"來自客戶的背書信加強了提案。"}]', 'phrasal verb'),
('estimated time of arrival', '', '', '[{"en":"The estimated time of arrival for the shipment is Friday.","zh-TW":"貨物的預計到達時間是週五。"},{"en":"Track your order to see the estimated time of arrival.","zh-TW":"追蹤您的訂單以查看預計到達時間。"}]', 'phrasal verb'),
('event planning', '', '', '[{"en":"She works in event planning for corporate conferences.","zh-TW":"她從事企業會議的活動策劃工作。"},{"en":"Good event planning requires attention to detail and flexibility.","zh-TW":"良好的活動策劃需要關注細節和靈活性。"}]', 'phrasal verb'),
('expense management', '', '', '[{"en":"Expense management software helps track all company spending.","zh-TW":"費用管理軟體有助於追蹤所有公司支出。"},{"en":"Effective expense management improves the company''s bottom line.","zh-TW":"有效的費用管理改善了公司的底線。"}]', 'phrasal verb'),
('feasibility report', '', '', '[{"en":"The feasibility report recommended proceeding with the expansion.","zh-TW":"可行性報告建議繼續推進擴張計劃。"},{"en":"A feasibility report must consider technical, financial, and market factors.","zh-TW":"可行性報告必須考慮技術、財務和市場因素。"}]', 'phrasal verb'),
('incentive pay', '', '', '[{"en":"Incentive pay is tied to achieving quarterly sales targets.","zh-TW":"績效獎金與完成季度銷售目標掛鈎。"},{"en":"The company introduced incentive pay to boost productivity.","zh-TW":"公司引入績效獎金以提升生產力。"}]', 'phrasal verb'),
('import duty', '', '', '[{"en":"The import duty on electronics was recently reduced.","zh-TW":"電子產品的進口關稅最近有所降低。"},{"en":"Importers must declare all goods and pay the applicable import duty.","zh-TW":"進口商必須申報所有貨物並繳納適用的進口關稅。"}]', 'phrasal verb'),
('logistics provider', '', '', '[{"en":"We switched to a more reliable logistics provider.","zh-TW":"我們換了一家更可靠的物流供應商。"},{"en":"A good logistics provider ensures timely delivery.","zh-TW":"良好的物流供應商確保及時交貨。"}]', 'phrasal verb'),
('net income', '', '', '[{"en":"The company reported a net income of $2 million last quarter.","zh-TW":"公司上季度報告淨收入為200萬美元。"},{"en":"Net income is a key measure of a company''s profitability.","zh-TW":"淨收入是衡量公司盈利能力的關鍵指標。"}]', 'phrasal verb'),
('operational cost', '', '', '[{"en":"Technology investments have reduced operational costs significantly.","zh-TW":"技術投資大幅降低了運營成本。"},{"en":"Streamlining processes helps control operational costs.","zh-TW":"簡化流程有助於控制運營成本。"}]', 'phrasal verb'),
('staffing agency', '', '', '[{"en":"The company used a staffing agency to fill temporary positions.","zh-TW":"公司通過人力資源機構填補臨時職位。"},{"en":"A staffing agency handles recruitment and payroll for temps.","zh-TW":"人力資源機構負責臨時員工的招聘和薪資。"}]', 'phrasal verb'),
('supply chain disruption', '', '', '[{"en":"The pandemic caused significant supply chain disruptions worldwide.","zh-TW":"疫情在全球範圍內造成了重大的供應鏈中斷。"},{"en":"Companies built larger inventories to buffer against supply chain disruptions.","zh-TW":"公司建立了更大的庫存以緩衝供應鏈中斷的影響。"}]', 'phrasal verb'),
('trade surplus', '', '', '[{"en":"The country maintained a trade surplus for five consecutive years.","zh-TW":"該國連續五年維持貿易順差。"},{"en":"A trade surplus strengthens a country''s currency.","zh-TW":"貿易順差有助於增強一國貨幣的強度。"}]', 'phrasal verb'),
('wage gap', '', '', '[{"en":"The company conducted a study to assess the gender wage gap.","zh-TW":"公司進行了一項研究以評估性別薪資差距。"},{"en":"Closing the wage gap requires transparent pay policies.","zh-TW":"縮小薪資差距需要透明的薪酬政策。"}]', 'phrasal verb'),
('balance of trade', '', '', '[{"en":"A positive balance of trade means exports exceed imports.","zh-TW":"貿易差額為正表示出口超過進口。"},{"en":"The country worked to improve its negative balance of trade.","zh-TW":"該國努力改善其負貿易差額。"}]', 'phrasal verb'),
('capacity utilization', '', '', '[{"en":"Higher capacity utilization leads to lower per-unit costs.","zh-TW":"更高的產能利用率可降低單位成本。"},{"en":"The factory operated at 90% capacity utilization during peak season.","zh-TW":"工廠在旺季以90%的產能利用率運作。"}]', 'phrasal verb'),
('financial disclosure', '', '', '[{"en":"Public companies are required to make regular financial disclosures.","zh-TW":"上市公司必須定期進行財務披露。"},{"en":"Full financial disclosure builds trust with investors.","zh-TW":"完整的財務披露建立了與投資者的信任。"}]', 'phrasal verb'),
('franchise fee', '', '', '[{"en":"The franchise fee covers the right to use the brand and systems.","zh-TW":"特許經營費包括使用品牌和系統的權利。"},{"en":"Prospective franchisees must pay an upfront franchise fee.","zh-TW":"準加盟商必須支付前期特許經營費。"}]', 'phrasal verb'),
('gross domestic product', '', '', '[{"en":"The country''s gross domestic product grew by 3% last year.","zh-TW":"該國的國內生產總值去年增長了3%。"},{"en":"Gross domestic product is the primary measure of national economic output.","zh-TW":"國內生產總值是衡量國家經濟產出的主要指標。"}]', 'phrasal verb'),
('inflationary pressure', '', '', '[{"en":"Inflationary pressure forced the central bank to raise interest rates.","zh-TW":"通脹壓力迫使央行提高利率。"},{"en":"Energy costs are a major source of inflationary pressure.","zh-TW":"能源成本是通脹壓力的主要來源。"}]', 'phrasal verb'),
('supply and demand', '', '', '[{"en":"Prices are determined by the law of supply and demand.","zh-TW":"價格由供求規律決定。"},{"en":"The shortage caused supply and demand to become severely imbalanced.","zh-TW":"短缺導致供求關係嚴重失衡。"}]', 'phrasal verb'),
('capital market', '', '', '[{"en":"The company raised funds by issuing bonds in the capital market.","zh-TW":"公司通過在資本市場發行債券籌集資金。"},{"en":"Capital markets provide businesses with long-term financing.","zh-TW":"資本市場為企業提供長期融資。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('economic forecast', '', '', '[{"en":"The bank released an optimistic economic forecast for next year.","zh-TW":"銀行發布了對明年樂觀的經濟預測。"},{"en":"Businesses use economic forecasts to plan their investment strategy.","zh-TW":"企業使用經濟預測來規劃其投資策略。"}]', 'phrasal verb'),
('fringe benefit', '', '', '[{"en":"Fringe benefits such as gym memberships boost morale.","zh-TW":"健身房會員等附加福利提升員工士氣。"},{"en":"Some fringe benefits are subject to income tax.","zh-TW":"部分附加福利需繳納所得稅。"}]', 'phrasal verb'),
('capital gain', '', '', '[{"en":"He realized a capital gain after selling the property.","zh-TW":"他出售房產後獲得了資本利得。"},{"en":"Capital gains are taxed at a lower rate than ordinary income.","zh-TW":"資本利得的稅率低於普通收入。"}]', 'phrasal verb'),
('arbitration clause', '', '', '[{"en":"The arbitration clause prevented costly court proceedings.","zh-TW":"仲裁條款防止了代價高昂的法庭訴訟。"},{"en":"Both parties agreed to include an arbitration clause in the contract.","zh-TW":"雙方同意在合約中加入仲裁條款。"}]', 'phrasal verb'),
('confidentiality agreement', '', '', '[{"en":"All employees must sign a confidentiality agreement on joining.","zh-TW":"所有員工在入職時必須簽署保密協議。"},{"en":"The confidentiality agreement covers product development plans.","zh-TW":"保密協議涵蓋產品開發計劃。"}]', 'phrasal verb'),
('due process', '', '', '[{"en":"All employees have the right to due process in disciplinary matters.","zh-TW":"所有員工在紀律事項中均享有正當程序的權利。"},{"en":"The court ruled that due process had not been followed.","zh-TW":"法院裁定未遵循正當程序。"}]', 'phrasal verb'),
('penalty clause', '', '', '[{"en":"The penalty clause specified 500 per day for late delivery.","zh-TW":"罰款條款規定每天延遲交貨罰款500元。"},{"en":"The penalty clause was enforced after repeated missed deadlines.","zh-TW":"在多次錯過截止日期後，罰款條款被執行。"}]', 'phrasal verb'),
('customs duty', '', '', '[{"en":"High customs duties made the imported goods uncompetitive.","zh-TW":"高關稅使進口商品失去競爭力。"},{"en":"The company applied for an exemption from customs duty on raw materials.","zh-TW":"公司申請了原材料的關稅豁免。"}]', 'phrasal verb'),
('delivery order', '', '', '[{"en":"The delivery order must be presented to collect the goods.","zh-TW":"必須出示交貨單才能提取貨物。"},{"en":"The warehouse released the goods upon receipt of the delivery order.","zh-TW":"倉庫在收到交貨單後放行了貨物。"}]', 'phrasal verb'),
('distribution center', '', '', '[{"en":"Orders are processed at the regional distribution center.","zh-TW":"訂單在區域配送中心處理。"},{"en":"The new distribution center reduced delivery times by 30%.","zh-TW":"新配送中心將交貨時間縮短了30%。"}]', 'phrasal verb'),
('drop shipment', '', '', '[{"en":"The online store uses a drop shipment model to avoid holding stock.","zh-TW":"網路商店使用代客發貨模式以避免持有庫存。"},{"en":"Drop shipment reduces warehousing costs for the retailer.","zh-TW":"代客發貨降低了零售商的倉儲成本。"}]', 'phrasal verb'),
('last-mile delivery', '', '', '[{"en":"Last-mile delivery accounts for most of the total shipping cost.","zh-TW":"最後一哩配送佔總運費的大部分。"},{"en":"Drone technology aims to revolutionize last-mile delivery.","zh-TW":"無人機技術旨在革新最後一哩配送。"}]', 'phrasal verb'),
('reorder point', '', '', '[{"en":"Stock fell below the reorder point, triggering a new order.","zh-TW":"庫存降至再訂購點以下，觸發了新訂單。"},{"en":"The reorder point accounts for lead time and average demand.","zh-TW":"再訂購點考慮了前置時間和平均需求。"}]', 'phrasal verb'),
('returns management', '', '', '[{"en":"A simple returns management policy increases customer confidence.","zh-TW":"簡單的退貨管理政策增加了客戶信心。"},{"en":"Reverse logistics focuses on returns management and recycling.","zh-TW":"逆向物流專注於退貨管理和回收利用。"}]', 'phrasal verb'),
('stock keeping unit', '', '', '[{"en":"Each product variant has its own stock keeping unit.","zh-TW":"每個產品變體都有自己的庫存單位。"},{"en":"SKU management simplifies inventory tracking across warehouses.","zh-TW":"庫存單位管理簡化了跨倉庫的庫存追蹤。"}]', 'phrasal verb'),
('third-party logistics', '', '', '[{"en":"The retailer outsourced delivery to a third-party logistics company.","zh-TW":"零售商將配送外包給第三方物流公司。"},{"en":"Third-party logistics providers offer warehousing and distribution services.","zh-TW":"第三方物流提供商提供倉儲和配送服務。"}]', 'phrasal verb'),
('application programming interface', '', '', '[{"en":"The payment gateway connects via an API to our e-commerce platform.","zh-TW":"支付閘道通過API連接到我們的電子商務平台。"},{"en":"Developers used the API to build a mobile application.","zh-TW":"開發人員使用API構建了行動應用程式。"}]', 'phrasal verb'),
('data mining', '', '', '[{"en":"Data mining revealed unexpected purchasing patterns.","zh-TW":"資料挖掘揭示了意想不到的購買模式。"},{"en":"The marketing team used data mining to identify high-value customers.","zh-TW":"市場行銷團隊使用資料挖掘來識別高價值客戶。"}]', 'phrasal verb'),
('enterprise resource planning', '', '', '[{"en":"The ERP system connects finance, HR, and supply chain in one platform.","zh-TW":"ERP系統將財務、人力資源和供應鏈連接在一個平台上。"},{"en":"Implementing ERP reduced data duplication and improved reporting.","zh-TW":"實施ERP減少了資料重複並改善了報告。"}]', 'phrasal verb'),
('software as a service', '', '', '[{"en":"The company switched to a SaaS model to reduce IT overhead.","zh-TW":"公司轉向SaaS模式以降低IT管理費用。"},{"en":"SaaS applications are accessible from any device with internet access.","zh-TW":"SaaS應用程式可從任何有網路連接的設備存取。"}]', 'phrasal verb'),
('user interface', '', '', '[{"en":"A clean user interface reduces the learning curve for new users.","zh-TW":"簡潔的使用者介面降低了新用戶的學習曲線。"},{"en":"The redesigned user interface improved customer satisfaction scores.","zh-TW":"重新設計的使用者介面提高了客戶滿意度分數。"}]', 'phrasal verb'),
('stakeholder communication', '', '', '[{"en":"Regular stakeholder communication prevents misunderstandings.","zh-TW":"定期的利害關係人溝通防止了誤解。"},{"en":"The project manager sent weekly updates as part of stakeholder communication.","zh-TW":"項目經理作為利害關係人溝通的一部分發送了每週更新。"}]', 'phrasal verb'),
('frequently asked questions', '', '', '[{"en":"Check the FAQ page before contacting customer support.","zh-TW":"在聯繫客戶支援之前，請查看常見問題頁面。"},{"en":"The FAQ was updated to address recent customer inquiries.","zh-TW":"常見問題已更新以解答最近的客戶詢問。"}]', 'phrasal verb'),
('response time', '', '', '[{"en":"The help desk targets a two-hour response time for all tickets.","zh-TW":"服務台的目標是對所有工單在兩小時內回應。"},{"en":"Faster response times significantly improve customer experience.","zh-TW":"更快的回應時間顯著改善了客戶體驗。"}]', 'phrasal verb'),
('user experience', '', '', '[{"en":"A smooth user experience keeps customers coming back.","zh-TW":"流暢的使用者體驗讓客戶持續回訪。"},{"en":"The app was redesigned based on user experience research.","zh-TW":"應用程式根據使用者體驗研究重新設計了。"}]', 'phrasal verb'),
('target audience', '', '', '[{"en":"The ad campaign was tailored to the target audience of young professionals.","zh-TW":"廣告活動專為年輕專業人士的目標受眾量身定制。"},{"en":"Understanding your target audience is the foundation of good marketing.","zh-TW":"了解您的目標受眾是良好行銷的基礎。"}]', 'phrasal verb'),
('assessed value', '', '', '[{"en":"Property taxes are based on the assessed value of the property.","zh-TW":"房產稅基於物業的評定價值計算。"},{"en":"The assessed value was lower than the market value.","zh-TW":"評定價值低於市場價值。"}]', 'phrasal verb'),
('equity release', '', '', '[{"en":"Equity release allowed the retiree to fund home improvements.","zh-TW":"房產淨值釋出使退休人士能夠為家居改善提供資金。"},{"en":"Equity release products are subject to strict regulation.","zh-TW":"房產淨值釋出產品受到嚴格監管。"}]', 'phrasal verb'),
('ground floor', '', '', '[{"en":"Investors who got in on the ground floor saw huge returns.","zh-TW":"在基礎階段進入的投資者獲得了豐厚回報。"},{"en":"The ground floor retail units command the highest rents.","zh-TW":"底層零售單位要求最高的租金。"}]', 'phrasal verb'),
('occupancy rate', '', '', '[{"en":"The office building maintained a 95% occupancy rate last year.","zh-TW":"辦公樓去年維持了95%的入住率。"},{"en":"A low occupancy rate indicates a weak property market.","zh-TW":"低入住率表明物業市場疲軟。"}]', 'phrasal verb'),
('real estate investment trust', '', '', '[{"en":"The REIT pays quarterly dividends from rental income.","zh-TW":"不動產投資信託從租金收入中每季支付股利。"},{"en":"REITs allow small investors to access commercial property markets.","zh-TW":"不動產投資信託允許小投資者進入商業地產市場。"}]', 'phrasal verb'),
('amenity kit', '', '', '[{"en":"Passengers in business class received an amenity kit.","zh-TW":"商務艙乘客收到了旅行盥洗包。"},{"en":"The amenity kit included a sleep mask, toothbrush, and earplugs.","zh-TW":"盥洗包內含睡眠眼罩、牙刷和耳塞。"}]', 'phrasal verb'),
('luggage allowance', '', '', '[{"en":"Business class offers a more generous luggage allowance than economy.","zh-TW":"商務艙提供比經濟艙更寬鬆的行李限額。"},{"en":"She paid an excess fee because she exceeded the luggage allowance.","zh-TW":"她因超出行李限額而支付了超重費。"}]', 'phrasal verb'),
('per diem', '', '', '[{"en":"Employees on business travel receive a per diem of 150 dollars.","zh-TW":"出差員工每天獲得150美元的日費津貼。"},{"en":"The per diem covers meals and incidental expenses.","zh-TW":"每日津貼涵蓋餐費和雜項支出。"}]', 'phrasal verb'),
('travel expense', '', '', '[{"en":"All travel expenses must be submitted within 30 days.","zh-TW":"所有差旅費必須在30天內提交報銷。"},{"en":"The company''s travel expense policy covers economy class for all flights.","zh-TW":"公司的差旅費政策涵蓋所有航班的經濟艙。"}]', 'phrasal verb'),
('account receivable financing', '', '', '[{"en":"Account receivable financing helped the firm bridge its cash gap.","zh-TW":"應收帳款融資幫助公司彌補了現金缺口。"},{"en":"Banks offer account receivable financing to businesses with slow-paying clients.","zh-TW":"銀行為有緩慢付款客戶的企業提供應收帳款融資。"}]', 'phrasal verb'),
('credit facility', '', '', '[{"en":"The company drew on its credit facility to cover operating expenses.","zh-TW":"公司動用了信貸額度來支付運營費用。"},{"en":"A credit facility provides flexible access to funds when needed.","zh-TW":"信貸額度在需要時提供靈活的資金存取。"}]', 'phrasal verb'),
('default risk', '', '', '[{"en":"Higher interest rates compensate lenders for taking on default risk.","zh-TW":"較高的利率補償了貸款方承擔的違約風險。"},{"en":"Credit ratings are used to assess the default risk of bond issuers.","zh-TW":"信用評等用於評估債券發行者的違約風險。"}]', 'phrasal verb'),
('fixed deposit', '', '', '[{"en":"He placed his savings in a 12-month fixed deposit.","zh-TW":"他將儲蓄存入12個月的定期存款。"},{"en":"Fixed deposit rates are higher than standard savings account rates.","zh-TW":"定期存款利率高於普通儲蓄帳戶利率。"}]', 'phrasal verb'),
('insurance premium', '', '', '[{"en":"The company pays the health insurance premium for all employees.","zh-TW":"公司為所有員工支付健康保險保費。"},{"en":"Premiums rose after the policyholder filed multiple claims.","zh-TW":"保單持有人多次申請索賠後，保費上漲了。"}]', 'phrasal verb'),
('premium waiver', '', '', '[{"en":"The premium waiver kicks in if the policyholder becomes disabled.","zh-TW":"如果保單持有人殘疾，保費豁免條款即生效。"},{"en":"A premium waiver rider was added to the life insurance policy.","zh-TW":"人壽保險保單添加了保費豁免附加條款。"}]', 'phrasal verb'),
('standing order', '', '', '[{"en":"She set up a standing order to pay rent on the first of each month.","zh-TW":"她設置了定期自動轉帳指令，在每月一日支付租金。"},{"en":"A standing order ensures bills are paid on time without manual action.","zh-TW":"定期轉帳指令確保帳單按時支付，無需手動操作。"}]', 'phrasal verb'),
('escalation matrix', '', '', '[{"en":"The escalation matrix defines who to contact for different severity levels.","zh-TW":"升級矩陣定義了針對不同嚴重程度應聯繫誰。"},{"en":"Following the escalation matrix ensures issues are resolved efficiently.","zh-TW":"遵循升級矩陣確保問題得到高效解決。"}]', 'phrasal verb'),
('feasibility study', '', '', '[{"en":"A feasibility study was conducted before committing to the new plant.","zh-TW":"在承諾建設新廠前進行了可行性研究。"},{"en":"The feasibility study determined the project was financially viable.","zh-TW":"可行性研究確定該項目在財務上是可行的。"}]', 'phrasal verb'),
('kick-off meeting', '', '', '[{"en":"The project kick-off meeting brought all stakeholders together.","zh-TW":"項目啟動會議將所有利害關係人聚集在一起。"},{"en":"The kick-off meeting established the timeline and key milestones.","zh-TW":"啟動會議確立了時間表和關鍵里程碑。"}]', 'phrasal verb'),
('project sponsor', '', '', '[{"en":"The project sponsor secured the funding for the new IT system.","zh-TW":"項目發起人為新IT系統爭取到了資金。"},{"en":"The project sponsor escalated the resource issue to the board.","zh-TW":"項目發起人將資源問題上報給了董事會。"}]', 'phrasal verb'),
('resource allocation', '', '', '[{"en":"Resource allocation was reviewed to align with the new priorities.","zh-TW":"資源分配根據新的優先事項進行了審查。"},{"en":"Poor resource allocation led to delays on three critical projects.","zh-TW":"資源分配不當導致三個關鍵項目延誤。"}]', 'phrasal verb'),
('export subsidy', '', '', '[{"en":"Export subsidies gave the domestic industry an unfair advantage.","zh-TW":"出口補貼給了國內產業不公平的優勢。"},{"en":"The WTO ruled that the export subsidies violated trade rules.","zh-TW":"世貿組織裁定出口補貼違反了貿易規則。"}]', 'phrasal verb'),
('import quota', '', '', '[{"en":"The government set an import quota on foreign steel.","zh-TW":"政府對外國鋼鐵設定了進口配額。"},{"en":"Import quotas protect domestic industries from foreign competition.","zh-TW":"進口配額保護國內產業免受外國競爭。"}]', 'phrasal verb'),
('market economy', '', '', '[{"en":"In a market economy, prices are determined by supply and demand.","zh-TW":"在市場經濟中，價格由供求關係決定。"},{"en":"The country transitioned to a market economy in the 1990s.","zh-TW":"該國在1990年代轉型為市場經濟。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('trade balance', '', '', '[{"en":"The country reported a trade balance deficit for the third consecutive year.","zh-TW":"該國連續第三年報告貿易逆差。"},{"en":"A trade balance surplus strengthens the domestic currency.","zh-TW":"貿易順差鞏固了本國貨幣。"}]', 'phrasal verb'),
('trade deficit', '', '', '[{"en":"The trade deficit widened as imports grew faster than exports.","zh-TW":"由於進口增速超過出口，貿易逆差擴大了。"},{"en":"The government sought to reduce the trade deficit through export promotion.","zh-TW":"政府通過促進出口尋求縮小貿易逆差。"}]', 'phrasal verb'),
('trade war', '', '', '[{"en":"The trade war between the two powers disrupted global supply chains.","zh-TW":"兩大國之間的貿易戰擾亂了全球供應鏈。"},{"en":"Companies restructured their supply chains to avoid trade war tariffs.","zh-TW":"企業重組了供應鏈以避免貿易戰關稅的影響。"}]', 'phrasal verb'),
('code of conduct', '', '', '[{"en":"All employees must sign and adhere to the code of conduct.","zh-TW":"所有員工必須簽署並遵守行為準則。"},{"en":"The code of conduct prohibits accepting gifts from suppliers.","zh-TW":"行為準則禁止接受供應商的禮品。"}]', 'phrasal verb'),
('policy compliance', '', '', '[{"en":"All staff must complete policy compliance training annually.","zh-TW":"所有員工每年必須完成政策合規培訓。"},{"en":"An internal audit checked policy compliance across all departments.","zh-TW":"內部審計檢查了所有部門的政策合規情況。"}]', 'phrasal verb'),
('advance payment', '', '', '[{"en":"A 30% advance payment is required before production begins.","zh-TW":"生產開始前需要支付30%的預付款。"},{"en":"The client made an advance payment to secure the delivery slot.","zh-TW":"客戶提前付款以確保交貨時間槽。"}]', 'phrasal verb'),
('bonus structure', '', '', '[{"en":"The bonus structure rewards top performers with up to 30% extra pay.","zh-TW":"獎金結構為頂尖表現者提供最高30%的額外薪酬。"},{"en":"The new bonus structure aligns employee incentives with company goals.","zh-TW":"新的獎金結構使員工激勵與公司目標保持一致。"}]', 'phrasal verb'),
('budget forecast', '', '', '[{"en":"The budget forecast projected a 10% increase in revenue.","zh-TW":"預算預測預計收入增長10%。"},{"en":"Management revised the budget forecast after the market downturn.","zh-TW":"在市場下行後，管理層修訂了預算預測。"}]', 'phrasal verb'),
('bulletin board', '', '', '[{"en":"Job vacancies are posted on the company bulletin board.","zh-TW":"職缺在公司公告欄上張貼。"},{"en":"The digital bulletin board displays real-time production metrics.","zh-TW":"數位公告欄顯示實時生產指標。"}]', 'phrasal verb'),
('commodity trading', '', '', '[{"en":"Commodity trading profits soared when oil prices surged.","zh-TW":"當油價飆升時，商品交易利潤大幅增加。"},{"en":"She joined a commodity trading desk specializing in agricultural products.","zh-TW":"她加入了專注於農業產品的商品交易部門。"}]', 'phrasal verb'),
('deadline extension', '', '', '[{"en":"She requested a deadline extension due to unexpected technical issues.","zh-TW":"她因意外的技術問題要求延長截止日期。"},{"en":"A two-week deadline extension was approved by the client.","zh-TW":"客戶批准了兩週的截止日期延長。"}]', 'phrasal verb'),
('deliverable schedule', '', '', '[{"en":"The deliverable schedule mapped out key milestones over 12 months.","zh-TW":"可交付成果時間表規劃了12個月內的關鍵里程碑。"},{"en":"Delays in the deliverable schedule triggered a project review.","zh-TW":"可交付成果時間表的延誤引發了項目審查。"}]', 'phrasal verb'),
('dismissal notice', '', '', '[{"en":"The employee received a dismissal notice effective immediately.","zh-TW":"員工收到了即時生效的解雇通知。"},{"en":"A dismissal notice must specify the reason for termination.","zh-TW":"解雇通知必須說明解雇原因。"}]', 'phrasal verb'),
('escalate costs', '', '', '[{"en":"Project costs escalated due to scope changes and material shortages.","zh-TW":"由於範圍變更和材料短缺，項目成本上升了。"},{"en":"The company took steps to prevent escalating labor costs.","zh-TW":"公司採取措施防止勞動力成本升高。"}]', 'phrasal verb'),
('infrastructure project', '', '', '[{"en":"The government launched a major infrastructure project to upgrade transport links.","zh-TW":"政府啟動了一項重大基礎設施項目以升級交通連接。"},{"en":"Infrastructure projects are typically financed through public-private partnerships.","zh-TW":"基礎設施項目通常通過公私合作方式融資。"}]', 'phrasal verb'),
('institutional investor', '', '', '[{"en":"Institutional investors hold 60% of the company''s shares.","zh-TW":"機構投資者持有公司60%的股份。"},{"en":"Strong institutional investor support boosted confidence in the IPO.","zh-TW":"機構投資者的強力支持提升了對首次公開募股的信心。"}]', 'phrasal verb'),
('key account', '', '', '[{"en":"Key accounts receive dedicated support from a senior team.","zh-TW":"重要客戶獲得資深團隊的專屬支持。"},{"en":"Losing a key account would significantly impact the company''s revenue.","zh-TW":"失去一個重要客戶將顯著影響公司收入。"}]', 'phrasal verb'),
('labor cost', '', '', '[{"en":"Automation helps reduce labor costs in high-volume manufacturing.","zh-TW":"自動化有助於降低大量製造中的勞動成本。"},{"en":"Rising labor costs prompted the company to relocate production.","zh-TW":"勞動成本上升促使公司遷移了生產地點。"}]', 'phrasal verb'),
('legal entity', '', '', '[{"en":"Each subsidiary is a separate legal entity with its own liabilities.","zh-TW":"每家子公司是一個獨立的法律實體，擁有自己的責任。"},{"en":"A legal entity must be established before applying for a business license.","zh-TW":"申請營業執照前必須建立一個法律實體。"}]', 'phrasal verb'),
('leveraged buyout', '', '', '[{"en":"Private equity firms often use leveraged buyouts to acquire companies.","zh-TW":"私募股權公司經常使用槓桿收購來收購公司。"},{"en":"The leveraged buyout was financed with 70% debt and 30% equity.","zh-TW":"槓桿收購以70%債務和30%股權融資。"}]', 'phrasal verb'),
('mutual fund', '', '', '[{"en":"She invested her savings in a balanced mutual fund.","zh-TW":"她將儲蓄投資於一支平衡型共同基金。"},{"en":"Mutual funds offer diversification at a lower cost than buying individual stocks.","zh-TW":"共同基金以比購買個股更低的成本提供多元化投資。"}]', 'phrasal verb'),
('overhead cost', '', '', '[{"en":"The company cut overhead costs by moving to a smaller office.","zh-TW":"公司通過遷往較小辦公室降低了間接成本。"},{"en":"Overhead costs must be factored into the product pricing.","zh-TW":"計算產品定價時必須考慮間接成本。"}]', 'phrasal verb'),
('partial payment', '', '', '[{"en":"The client made a partial payment of 50% upon signing the contract.","zh-TW":"客戶在簽署合約時支付了50%的部分款項。"},{"en":"Partial payment terms helped the startup manage its cash flow.","zh-TW":"部分付款條款幫助新創公司管理了現金流。"}]', 'phrasal verb'),
('recurring revenue', '', '', '[{"en":"SaaS companies depend heavily on recurring revenue from subscriptions.","zh-TW":"SaaS公司嚴重依賴訂閱的循環收入。"},{"en":"Recurring revenue provides predictable cash flow for the business.","zh-TW":"循環收入為業務提供了可預測的現金流。"}]', 'phrasal verb'),
('regulatory body', '', '', '[{"en":"All financial institutions must be registered with the relevant regulatory body.","zh-TW":"所有金融機構必須向相關監管機構登記。"},{"en":"The regulatory body launched an investigation into the trading practices.","zh-TW":"監管機構對交易行為展開了調查。"}]', 'phrasal verb'),
('remittance advice', '', '', '[{"en":"Please find the attached remittance advice for payment made today.","zh-TW":"請查找今天已付款的隨附匯款通知。"},{"en":"Remittance advice helps the recipient match payment to the invoice.","zh-TW":"匯款通知幫助收款人將付款與發票匹配。"}]', 'phrasal verb'),
('subsidiary company', '', '', '[{"en":"The subsidiary company operates independently in the Asian market.","zh-TW":"子公司在亞洲市場獨立運營。"},{"en":"Revenue from the subsidiary company contributed 20% to group earnings.","zh-TW":"子公司的收入貢獻了集團盈利的20%。"}]', 'phrasal verb'),
('tender offer', '', '', '[{"en":"The company launched a tender offer at a 25% premium over market price.","zh-TW":"公司以高出市場價格25%的溢價發起了要約收購。"},{"en":"Shareholders voted to accept the tender offer.","zh-TW":"股東投票接受了要約收購。"}]', 'phrasal verb'),
('third party', '', '', '[{"en":"A third party was brought in to independently verify the results.","zh-TW":"引入了第三方對結果進行獨立核實。"},{"en":"The contract requires all disputes to be resolved through a third party.","zh-TW":"合約要求所有爭議通過第三方解決。"}]', 'phrasal verb'),
('transaction processing', '', '', '[{"en":"The bank''s transaction processing system handles millions of payments daily.","zh-TW":"銀行的交易處理系統每天處理數百萬筆付款。"},{"en":"Transaction processing speed improved after the system upgrade.","zh-TW":"系統升級後交易處理速度提高了。"}]', 'phrasal verb'),
('transparency report', '', '', '[{"en":"The tech company published a transparency report on government data requests.","zh-TW":"科技公司發布了一份關於政府資料請求的透明度報告。"},{"en":"Transparency reports help build trust with customers and regulators.","zh-TW":"透明度報告有助於建立客戶和監管機構的信任。"}]', 'phrasal verb'),
('acquisition cost', '', '', '[{"en":"Customer acquisition cost fell after the new referral program launched.","zh-TW":"新推薦計劃推出後，客戶取得成本下降了。"},{"en":"The acquisition cost of the target company included a 20% premium.","zh-TW":"目標公司的收購成本包括20%的溢價。"}]', 'phrasal verb'),
('appropriate funds', '', '', '[{"en":"Congress appropriated additional funds for the disaster relief effort.","zh-TW":"國會為災難救援工作撥出了額外資金。"},{"en":"The board appropriated reserves to cover the unexpected expenses.","zh-TW":"董事會撥出了儲備金以支付意外費用。"}]', 'phrasal verb'),
('assign responsibility', '', '', '[{"en":"Responsibility for data security was assigned to the IT director.","zh-TW":"資料安全的責任被指派給了IT總監。"},{"en":"Each project milestone had an assigned responsibility owner.","zh-TW":"每個項目里程碑都有指派的責任人。"}]', 'phrasal verb'),
('certification of origin', '', '', '[{"en":"A certificate of origin is required for preferential tariff treatment.","zh-TW":"優惠關稅待遇需要原產地證明書。"},{"en":"The exporter submitted the certificate of origin to customs.","zh-TW":"出口商向海關提交了原產地證明書。"}]', 'phrasal verb'),
('circulate a document', '', '', '[{"en":"The draft policy was circulated for comment before finalization.","zh-TW":"政策草案在定案前傳閱徵求意見。"},{"en":"The agenda was circulated to all attendees a week before the meeting.","zh-TW":"議程在會議前一週傳閱給所有與會者。"}]', 'phrasal verb'),
('closing price', '', '', '[{"en":"The stock''s closing price rose by 3% on strong earnings news.","zh-TW":"受強勁盈利消息影響，股票收盤價上漲了3%。"},{"en":"Investors track the closing price to assess daily market performance.","zh-TW":"投資者追蹤收盤價以評估每日市場表現。"}]', 'phrasal verb'),
('commodity price', '', '', '[{"en":"Rising commodity prices squeezed profit margins across the industry.","zh-TW":"大宗商品價格上漲壓縮了整個行業的利潤率。"},{"en":"The budget was revised after a sharp drop in commodity prices.","zh-TW":"大宗商品價格急劇下跌後，預算進行了修訂。"}]', 'phrasal verb'),
('conduct a survey', '', '', '[{"en":"The HR team conducted a survey on workplace satisfaction.","zh-TW":"人力資源團隊對工作場所滿意度進行了調查。"},{"en":"Market research was conducted via an online survey.","zh-TW":"市場研究通過線上調查進行。"}]', 'phrasal verb'),
('contingency reserve', '', '', '[{"en":"A 10% contingency reserve was included in the project budget.","zh-TW":"項目預算中包含了10%的應急儲備金。"},{"en":"The team drew on the contingency reserve to cover unexpected costs.","zh-TW":"團隊動用了應急儲備金來支付意外費用。"}]', 'phrasal verb'),
('corporate bond', '', '', '[{"en":"The company issued corporate bonds at a yield of 3.5%.","zh-TW":"公司以3.5%的收益率發行了公司債券。"},{"en":"Corporate bonds offer higher yields than government bonds.","zh-TW":"公司債券比政府債券提供更高的收益率。"}]', 'phrasal verb'),
('cost centre', '', '', '[{"en":"The IT department operates as a cost centre within the organization.","zh-TW":"IT部門作為組織內的成本中心運營。"},{"en":"Cost centre managers must justify all expenditure requests.","zh-TW":"成本中心管理者必須為所有支出申請提供理由。"}]', 'phrasal verb'),
('customer acquisition', '', '', '[{"en":"Digital marketing reduced customer acquisition costs by 40%.","zh-TW":"數位行銷將客戶獲取成本降低了40%。"},{"en":"The focus shifted from customer acquisition to customer retention.","zh-TW":"重點從客戶獲取轉向了客戶保留。"}]', 'phrasal verb'),
('deliver on time', '', '', '[{"en":"The contractor delivered the project on time and within budget.","zh-TW":"承包商按時且在預算內交付了項目。"},{"en":"Failing to deliver on time resulted in penalty charges.","zh-TW":"未能按時交付導致了違約罰款。"}]', 'phrasal verb'),
('depreciation rate', '', '', '[{"en":"The depreciation rate for machinery is set at 20% per annum.","zh-TW":"機械的折舊率設定為每年20%。"},{"en":"A higher depreciation rate reduces taxable income in early years.","zh-TW":"較高的折舊率在前幾年降低了應稅收入。"}]', 'phrasal verb'),
('digital signature', '', '', '[{"en":"Documents can be signed using a legally valid digital signature.","zh-TW":"文件可以使用具有法律效力的數位簽章簽署。"},{"en":"The digital signature confirmed the document''s authenticity.","zh-TW":"數位簽章確認了文件的真實性。"}]', 'phrasal verb'),
('direct cost', '', '', '[{"en":"Direct costs include raw materials, packaging, and direct labor.","zh-TW":"直接成本包括原材料、包裝和直接人工。"},{"en":"Reducing direct costs improves the gross profit margin.","zh-TW":"降低直接成本改善了毛利率。"}]', 'phrasal verb'),
('discretionary spending', '', '', '[{"en":"The company reduced discretionary spending to preserve cash.","zh-TW":"公司削減了可裁量支出以保存現金。"},{"en":"Consumers tend to cut discretionary spending during recessions.","zh-TW":"消費者在經濟衰退期間傾向於削減可裁量支出。"}]', 'phrasal verb'),
('document management', '', '', '[{"en":"The new document management system reduced retrieval time by 60%.","zh-TW":"新的文件管理系統將文件檢索時間縮短了60%。"},{"en":"Secure document management is essential for compliance.","zh-TW":"安全的文件管理對合規至關重要。"}]', 'phrasal verb'),
('earnings before interest and tax', '', '', '[{"en":"A higher EBIT indicates stronger operational efficiency.","zh-TW":"較高的息稅前利潤表明更強的運營效率。"},{"en":"EBIT is used to compare profitability across companies with different capital structures.","zh-TW":"息稅前利潤用於比較具有不同資本結構的公司的盈利能力。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('endorsement fee', '', '', '[{"en":"The athlete earned a substantial endorsement fee for the campaign.","zh-TW":"運動員為廣告活動賺取了可觀的代言費。"},{"en":"Endorsement fees are a significant part of celebrity income.","zh-TW":"代言費是名人收入的重要組成部分。"}]', 'phrasal verb'),
('equity capital', '', '', '[{"en":"The company strengthened its equity capital base through a rights issue.","zh-TW":"公司通過配股增強了其股本基礎。"},{"en":"Equity capital does not require repayment but dilutes existing shareholders.","zh-TW":"股本不需要償還，但會稀釋現有股東的股份。"}]', 'phrasal verb'),
('escrow account', '', '', '[{"en":"The purchase price was placed in an escrow account pending due diligence.","zh-TW":"購買價款存放在托管帳戶中，等待完成盡職調查。"},{"en":"An escrow account protects both buyer and seller during a property transaction.","zh-TW":"托管帳戶在房產交易中保護買方和賣方雙方。"}]', 'phrasal verb'),
('exchange-traded fund', '', '', '[{"en":"ETFs offer low-cost exposure to diversified portfolios.","zh-TW":"交易所買賣基金提供低成本的多元化投資組合敞口。"},{"en":"She shifted from actively managed funds to ETFs to reduce fees.","zh-TW":"她從主動管理基金轉向了交易所買賣基金以降低費用。"}]', 'phrasal verb'),
('exclusivity clause', '', '', '[{"en":"The distribution agreement includes a two-year exclusivity clause.","zh-TW":"分銷協議包含兩年的獨家條款。"},{"en":"The exclusivity clause prevented the supplier from selling to rivals.","zh-TW":"獨家條款阻止了供應商向競爭對手出售。"}]', 'phrasal verb'),
('expansion plan', '', '', '[{"en":"The board approved a three-year expansion plan into Southeast Asia.","zh-TW":"董事會批准了進入東南亞的三年擴張計劃。"},{"en":"The expansion plan was delayed due to market uncertainty.","zh-TW":"擴張計劃因市場不確定性而延遲了。"}]', 'phrasal verb'),
('expert witness', '', '', '[{"en":"The company hired an expert witness to support its case.","zh-TW":"公司聘請了一名專家證人支持其案件。"},{"en":"The expert witness provided a detailed valuation report.","zh-TW":"專家證人提供了詳細的估值報告。"}]', 'phrasal verb'),
('fair trade', '', '', '[{"en":"The coffee was certified as fair trade by an independent body.","zh-TW":"咖啡被獨立機構認證為公平貿易產品。"},{"en":"Fair trade principles ensure workers in developing countries receive fair wages.","zh-TW":"公平貿易原則確保發展中國家的工人獲得公平薪資。"}]', 'phrasal verb'),
('financial audit', '', '', '[{"en":"The external financial audit was completed by the end of March.","zh-TW":"外部財務審計於三月底完成。"},{"en":"A clean financial audit report boosted investor confidence.","zh-TW":"乾淨的財務審計報告增強了投資者信心。"}]', 'phrasal verb'),
('financial risk', '', '', '[{"en":"The company''s expansion into new markets introduced significant financial risk.","zh-TW":"公司進入新市場引入了重大財務風險。"},{"en":"Diversification is a key tool for managing financial risk.","zh-TW":"多元化是管理財務風險的關鍵工具。"}]', 'phrasal verb'),
('fiscal deficit', '', '', '[{"en":"The government introduced austerity measures to cut the fiscal deficit.","zh-TW":"政府引入緊縮措施以削減財政赤字。"},{"en":"A growing fiscal deficit raised concerns among international lenders.","zh-TW":"不斷擴大的財政赤字引發了國際貸款方的擔憂。"}]', 'phrasal verb'),
('fixed assets', '', '', '[{"en":"Fixed assets include property, machinery, and equipment.","zh-TW":"固定資產包括房產、機械和設備。"},{"en":"The company increased its fixed assets through the new factory investment.","zh-TW":"公司通過新工廠投資增加了固定資產。"}]', 'phrasal verb'),
('floating rate', '', '', '[{"en":"The loan carries a floating rate tied to the central bank benchmark.","zh-TW":"貸款採用與中央銀行基準利率掛鉤的浮動利率。"},{"en":"Floating rate bonds protect investors from rising interest rates.","zh-TW":"浮動利率債券保護投資者免受利率上升影響。"}]', 'phrasal verb'),
('force of habit', '', '', '[{"en":"Process changes often fail due to the force of habit.","zh-TW":"流程變革往往因習慣的力量而失敗。"},{"en":"Employees returned to old methods by force of habit after training.","zh-TW":"員工在培訓後出於習慣慣性回到了舊方法。"}]', 'phrasal verb'),
('foreclosure sale', '', '', '[{"en":"Investors bought properties cheaply at foreclosure sales.","zh-TW":"投資者在法拍屋出售中以低價購買了房產。"},{"en":"A foreclosure sale recovered partial payment for the creditor.","zh-TW":"法拍屋出售為債權人回收了部分款項。"}]', 'phrasal verb'),
('foreign direct investment', '', '', '[{"en":"The government introduced incentives to attract foreign direct investment.","zh-TW":"政府推出激勵措施以吸引外國直接投資。"},{"en":"Foreign direct investment boosted employment in the manufacturing sector.","zh-TW":"外國直接投資促進了製造業的就業。"}]', 'phrasal verb'),
('formal proposal', '', '', '[{"en":"Please submit a formal proposal outlining costs and timelines.","zh-TW":"請提交概述成本和時間表的正式提案。"},{"en":"The formal proposal was reviewed by the procurement committee.","zh-TW":"正式提案由採購委員會審查了。"}]', 'phrasal verb'),
('funding gap', '', '', '[{"en":"A funding gap of 5 million needed to be filled before construction.","zh-TW":"施工前需要填補500萬元的資金缺口。"},{"en":"The nonprofit sought donors to close its annual funding gap.","zh-TW":"非營利組織尋求捐款者填補其年度資金缺口。"}]', 'phrasal verb'),
('goodwill amortization', '', '', '[{"en":"Goodwill amortization reduced the reported earnings by 5 million.","zh-TW":"商譽攤銷將報告盈利減少了500萬元。"},{"en":"Some accounting standards require goodwill amortization over 10 years.","zh-TW":"某些會計準則要求在10年內攤銷商譽。"}]', 'phrasal verb'),
('governance framework', '', '', '[{"en":"The new governance framework defined roles and accountability clearly.","zh-TW":"新治理框架清楚地定義了角色和問責制。"},{"en":"A robust governance framework is essential for publicly listed companies.","zh-TW":"強健的治理框架對於上市公司至關重要。"}]', 'phrasal verb'),
('growth rate', '', '', '[{"en":"The company achieved a compound annual growth rate of 15%.","zh-TW":"公司實現了15%的複合年增長率。"},{"en":"GDP growth rate slowed to 2% amid global uncertainties.","zh-TW":"在全球不確定性中，GDP增長率放緩至2%。"}]', 'phrasal verb'),
('high-value client', '', '', '[{"en":"High-value clients receive dedicated account management.","zh-TW":"高價值客戶獲得專屬客戶管理服務。"},{"en":"The sales strategy focused on attracting and retaining high-value clients.","zh-TW":"銷售策略專注於吸引和保留高價值客戶。"}]', 'phrasal verb'),
('horizontal integration', '', '', '[{"en":"The acquisition represented horizontal integration in the retail sector.","zh-TW":"此次收購代表了零售業的橫向整合。"},{"en":"Horizontal integration increases market share but may trigger antitrust reviews.","zh-TW":"橫向整合增加了市場份額，但可能觸發反壟斷審查。"}]', 'phrasal verb'),
('idle capacity', '', '', '[{"en":"Idle capacity was used to take on subcontracting work.","zh-TW":"閒置產能被用於承接分包工作。"},{"en":"High idle capacity indicates inefficient resource use.","zh-TW":"高閒置產能表明資源使用效率低下。"}]', 'phrasal verb'),
('increase market share', '', '', '[{"en":"The company reduced prices to increase market share.","zh-TW":"公司降價以增加市場份額。"},{"en":"Innovative products helped the firm increase market share rapidly.","zh-TW":"創新產品幫助公司迅速增加了市場份額。"}]', 'phrasal verb'),
('institutional framework', '', '', '[{"en":"A stable institutional framework attracts long-term investment.","zh-TW":"穩定的制度框架吸引了長期投資。"},{"en":"The institutional framework ensures fair competition in the market.","zh-TW":"制度框架確保了市場中的公平競爭。"}]', 'phrasal verb'),
('investment grade', '', '', '[{"en":"The company''s bonds were upgraded to investment grade by Moody''s.","zh-TW":"該公司的債券被穆迪升級為投資級別。"},{"en":"Investment grade bonds offer lower yields but greater security.","zh-TW":"投資級別債券提供較低收益率但更高安全性。"}]', 'phrasal verb'),
('invoice discounting', '', '', '[{"en":"Invoice discounting improved the firm''s short-term liquidity.","zh-TW":"發票貼現改善了公司的短期流動性。"},{"en":"The bank offered invoice discounting at a rate of 1.5%.","zh-TW":"銀行以1.5%的利率提供發票貼現服務。"}]', 'phrasal verb'),
('key risk indicator', '', '', '[{"en":"Key risk indicators are reviewed weekly by the risk committee.","zh-TW":"關鍵風險指標每週由風險委員會審查。"},{"en":"An increase in key risk indicators triggered an urgent review.","zh-TW":"關鍵風險指標的上升觸發了緊急審查。"}]', 'phrasal verb'),
('key stakeholder', '', '', '[{"en":"Key stakeholders were consulted at every stage of the project.","zh-TW":"在項目的每個階段都諮詢了主要利害關係人。"},{"en":"The report summarized key stakeholder concerns and recommendations.","zh-TW":"報告總結了主要利害關係人的關切和建議。"}]', 'phrasal verb'),
('labor shortage', '', '', '[{"en":"Labor shortages pushed wages higher in the construction industry.","zh-TW":"勞動力短缺推動了建築業工資上漲。"},{"en":"Automation was introduced to offset the impact of labor shortages.","zh-TW":"引入自動化以抵消勞動力短缺的影響。"}]', 'phrasal verb'),
('lead time reduction', '', '', '[{"en":"Lead time reduction was a key goal of the supply chain project.","zh-TW":"縮短前置時間是供應鏈項目的關鍵目標。"},{"en":"Closer collaboration with suppliers enabled significant lead time reduction.","zh-TW":"與供應商更緊密的合作實現了顯著的前置時間縮短。"}]', 'phrasal verb'),
('legal advisor', '', '', '[{"en":"The company retained a legal advisor to review the acquisition.","zh-TW":"公司聘請了法律顧問審查收購事宜。"},{"en":"A legal advisor confirmed the contract terms were enforceable.","zh-TW":"法律顧問確認合約條款具有可執行性。"}]', 'phrasal verb'),
('line manager', '', '', '[{"en":"All performance feedback is channeled through the line manager.","zh-TW":"所有績效反饋都通過直屬主管傳達。"},{"en":"She discussed the promotion opportunity with her line manager.","zh-TW":"她與直屬主管討論了晉升機會。"}]', 'phrasal verb'),
('liquidity risk', '', '', '[{"en":"A sudden withdrawal triggered a liquidity risk event.","zh-TW":"突然的提款觸發了流動性風險事件。"},{"en":"Maintaining a cash reserve reduces exposure to liquidity risk.","zh-TW":"維持現金儲備降低了對流動性風險的暴露。"}]', 'phrasal verb'),
('long position', '', '', '[{"en":"The fund took a long position in technology stocks.","zh-TW":"基金持有科技股的多頭部位。"},{"en":"A long position profits when asset prices rise.","zh-TW":"多頭部位在資產價格上漲時獲利。"}]', 'phrasal verb'),
('loss provision', '', '', '[{"en":"The bank increased its loss provision for bad loans.","zh-TW":"銀行增加了壞帳損失準備金。"},{"en":"A large loss provision reduced the reported profit significantly.","zh-TW":"大額損失準備金顯著降低了報告利潤。"}]', 'phrasal verb'),
('lower breakeven', '', '', '[{"en":"Cutting fixed costs helped the company lower its breakeven point.","zh-TW":"削減固定成本幫助公司降低了損益平衡點。"},{"en":"The restructuring was designed to lower the breakeven quickly.","zh-TW":"重組旨在快速降低損益平衡點。"}]', 'phrasal verb'),
('maintain records', '', '', '[{"en":"Companies are required to maintain records for at least seven years.","zh-TW":"公司須保存至少七年的記錄。"},{"en":"The IT department maintains records of all system access.","zh-TW":"IT部門保存所有系統存取記錄。"}]', 'phrasal verb'),
('majority shareholder', '', '', '[{"en":"The family remained the majority shareholder after the IPO.","zh-TW":"家族在首次公開募股後仍是多數股東。"},{"en":"The majority shareholder has significant control over board decisions.","zh-TW":"多數股東對董事會決策有重大控制力。"}]', 'phrasal verb'),
('management buy-in', '', '', '[{"en":"Gaining management buy-in was essential for the cultural transformation.","zh-TW":"獲得管理層認同對文化轉型至關重要。"},{"en":"The management buy-in was funded by private equity.","zh-TW":"外部管理層收購由私募股權資助。"}]', 'phrasal verb'),
('management buyout', '', '', '[{"en":"The management buyout allowed the founders to exit while keeping the business running.","zh-TW":"管理層收購允許創辦人退出同時保持業務運營。"},{"en":"A leveraged management buyout was financed with bank loans.","zh-TW":"槓桿管理層收購通過銀行貸款融資。"}]', 'phrasal verb'),
('margin call', '', '', '[{"en":"The investor received a margin call as the stock price fell sharply.","zh-TW":"隨著股價急劇下跌，投資者收到了補倉通知。"},{"en":"Failing to meet a margin call results in forced liquidation.","zh-TW":"未能滿足補倉通知將導致強制平倉。"}]', 'phrasal verb'),
('material breach', '', '', '[{"en":"A material breach entitles the other party to terminate the contract.","zh-TW":"實質性違約賦予另一方終止合約的權利。"},{"en":"The delayed payment was deemed a material breach.","zh-TW":"延遲付款被認定為實質性違約。"}]', 'phrasal verb'),
('matrix management', '', '', '[{"en":"Matrix management enables flexible resource sharing across projects.","zh-TW":"矩陣式管理實現了跨項目的靈活資源共享。"},{"en":"Clear communication is essential in a matrix management environment.","zh-TW":"在矩陣式管理環境中，清晰的溝通至關重要。"}]', 'phrasal verb'),
('meet targets', '', '', '[{"en":"The sales team met all its quarterly targets for the first time.","zh-TW":"銷售團隊首次達成了所有季度目標。"},{"en":"Incentive bonuses are paid only when staff meet their individual targets.","zh-TW":"只有當員工達到個人目標時才發放績效獎金。"}]', 'phrasal verb'),
('multinational corporation', '', '', '[{"en":"The multinational corporation employs over 100000 people worldwide.","zh-TW":"這家跨國公司在全球雇用了超過10萬名員工。"},{"en":"Multinational corporations benefit from economies of scale.","zh-TW":"跨國公司從規模經濟中獲益。"}]', 'phrasal verb'),
('net assets', '', '', '[{"en":"The company grew its net assets from 20 million to 50 million.","zh-TW":"公司的淨資產從2000萬元增長到5000萬元。"},{"en":"Net assets represent the book value of shareholders equity.","zh-TW":"淨資產代表股東權益的帳面價值。"}]', 'phrasal verb'),
('net profit margin', '', '', '[{"en":"The company improved its net profit margin from 5% to 8%.","zh-TW":"公司將淨利率從5%提高到了8%。"},{"en":"A higher net profit margin indicates stronger financial efficiency.","zh-TW":"較高的淨利率表明更強的財務效率。"}]', 'phrasal verb'),
('net working capital', '', '', '[{"en":"Positive net working capital means the company can meet short-term obligations.","zh-TW":"正的淨營運資金意味著公司能夠履行短期義務。"},{"en":"The acquisition improved the buyer''s net working capital position.","zh-TW":"收購改善了買方的淨營運資金狀況。"}]', 'phrasal verb');